sketches.source:
setcpm(50/4)

// A 10 Hz binaural beat in the alpha range: each ear is detuned by 5 Hz. Keep it quiet
drone: note("[d2,a2]").slow(4).s("sine").binaural(10)
  .attack(4).sustain(1).release(6).gain(.12)

// A soft pad whose filter breathes over eight bars: Dmaj7, Bm7, Gmaj7, A
pad: note("<[d3,a3,c#4,f#4] [b2,f#3,a3,d4] [g2,d3,b3,f#4] [a2,e3,a3,c#4]>").slow(2)
  .s("sawtooth").unison(3).detune(.2).lpf(sine.range(500, 1100).slow(8))
  .attack(3).release(4).room(.7).size(.9).gain(.12)

// A singing bowl marks every four bars
bowl: note("<d4 ~ ~ ~>").s("sine").fm(1.2).fmh(2.76)
  .decay(6).sustain(0).release(6).space("hall").gain(.14)

// Soft, wide air: unrelated pink noise in each ear
air: s("pink").slow(8).icorr(.15).hpf(400).lpf(2500).gain(.025)

setcpm(48/4)

// The pad steps through the interaural phase, a chord at a time: C, Am, F, G
// 0 degrees: centred. 90: looser. 180: diffuse and all around, and nearly gone in mono
pad: note("<[c3,g3,e4] [a2,e3,c4] [f2,c3,a3] [g2,d3,b3]>").slow(2)
  .s("triangle").iphase("<0 0 90 90 180 180 90 90>")
  .attack(2).sustain(1).release(3).lpf(1400).gain(.18)

// One breath every two bars, ten seconds: breathe in as the air rises, out as it fades
breath: s("pink").slow(2).hpf(200).lpf(700).attack(4).release(5).gain(.04)

// Far-off bells every few breaths
bell: note("<g4 ~ e4 ~ c5 ~ ~ ~>").s("sine").fm(2).fmh(2.76)
  .decay(4).sustain(0).release(4).room(.7).gain(.08)

// A low root, the same in both ears
bass: note("<c2 a1 f1 g1>").slow(2).s("sine").attack(2).sustain(.8).release(3).gain(.2)

setcpm(64/4)

// A low-pass on each ear alone, sweeping in opposite directions every eight bars
// The level stays put; only the brightness drifts: Fmaj7, Dm7, Bbmaj7, C
figure: n("0 2 4 6 4 2 0 2").add("<0 -2 -4 -3>").scale("F:major")
  .s("triangle").timbre("soft")
  .lcutoff(saw.range(500, 3000).slow(8)).rcutoff(isaw.range(500, 3000).slow(8))
  .attack(.005).decay(.8).sustain(.05).release(1).room(.5).gain(.2)

// A low root, the same in both ears
bass: note("<f2 d2 bb1 c2>").s("sine").attack(.3).sustain(.6).release(1).gain(.26)

// A fire on your left, a clock on your right, and a warm floor of brown noise
fire: s("fire").slow(4).intensity(.25).density(5).azimuth(-60).distance(3).gain(.12)
clock: s("tick ~ tick ~").azimuth(70).distance(4).gain(.04)
floor: s("brown").slow(8).lpf(500).gain(.06)

setcpm(66/4)

// One seeded melody, and a soft felt touch, named once
const melody = n(irand(8).segment(8)).scale("A:minor pentatonic")
const felt = (x) => x.s("triangle").timbre("soft")
  .attack(.005).decay(1).sustain(.05).release(1.2).room(.6)

// ild makes the right ear louder; earswap flips it, so the hands trade ears every four bars
right: melody.transpose(12).degradeBy(.6).felt()
  .ild(6).earswap("<0 0 0 0 1 1 1 1>").seed("hands").gain(.22)
left: melody.transpose(-12).undegradeBy(.3).felt()
  .ild(6).earswap("<1 1 1 1 0 0 0 0>").seed("hands").gain(.2)

// A held fifth, the same in both ears, and a stream far off
drone: note("[a1,e2]").slow(8).s("sine").attack(3).sustain(1).release(4).gain(.14)
stream: s("stream").slow(4).distance(5).gain(.12)

setcpm(60/4)

// earsh raises the right ear and lowers the left by half the value each
// The strings breathe out and back: 2, 4, 8, then 4 cents, two bars each: G, Em, C, D
pad: note("<[g2,d3,b3] [e2,b2,g3] [c3,g3,e4] [d3,a3,f#4]>").slow(2)
  .s("sawtooth").unison(2).detune(.1).earsh("<2 2 4 4 8 8 4 4>")
  .lpf(1000).attack(2).sustain(1).release(3).room(.7).size(.9).gain(.12)

// A plucked tine over a small wooden box
const kalimba = (x) => x.s("sine").fm(.8).fmh(5.4)
  .attack(.001).decay(1).sustain(0).release(.9).body("box").bodymix(.35).room(.4)

// The kalimba, the same in both ears
tines: note("<[g4 b4 d4 d5] [e4 g4 b3 b4] [c4 e4 g4 c5] [d4 f#4 a3 a4]>").slow(2)
  .kalimba().gain(.22)

// A light breeze
breeze: s("wind").slow(8).intensity(.15).gain(.06)

setcpm(58/4)

// From about 1 to 30 ms a delay between the ears keeps the harp on the leading side but widens it
// C, Am, F, G
harp: note("<[c3 g3 e4 g3 c4 g3 e4 g3] [a2 e3 c4 e3 a3 e3 c4 e3] [f2 c3 a3 c3 f3 c3 a3 c3] [g2 d3 b3 d3 g3 d3 b3 d3]>")
  .s("triangle").timbre("soft").attack(.002).decay(1.2).sustain(0).release(1.2)
  .itd("<1 6 12 20>").room(.5).gain(.22)

// The flute sings in the centre, with no delay at all
flute: note("<[e5@3 d5 c5@4] [c5@2 e5@2 a4@4] [a4@3 c5 f5@4] [d5@6 ~@2]>")
  .s("sine").timbre("hollow").vib(4.5).vibdepth(.1)
  .attack(.2).sustain(.6).release(1).room(.6).gain(.2)

// A soft root, and rain heard through the glass
bass: note("<c2 a1 f1 g1>").s("sine").attack(.2).sustain(.6).release(1).gain(.26)
rain: s("rain").slow(4).intensity(.3).occlude(.6).gain(.14)

setcpm(52/4)

// Soft breaths of noise: the same in both ears, but one ear is phase-shifted in a narrow band
// Neither ear alone hears a tone; together they carry a slow phrase
tune: s("white*4").dichotic("<[392 440 494 440] [330 392 440 392] [294 330 392 330] [392 392 392 392]>")
  .dichoticq(30).attack(.15).sustain(1).release(.3).gain(.1)

// A quiet hint: the first phrase on a sine, once every four bars
hint: note("<[g4 a4 b4 a4] ~ ~ ~>").s("sine")
  .decay(.4).sustain(.2).release(.4).gain(.06)

// A soft pad holding the key: G, Em, D, G
pad: note("<[g2,d3,b3] [e2,b2,g3] [d2,a2,f#3] [g2,d3,b3]>")
  .s("triangle").timbre("soft").attack(1.5).sustain(.6).release(3)
  .lpf(900).room(.6).gain(.12)

// A singing bowl at the start of each phrase
bowl: note("<g3 ~ ~ ~>").s("sine").fm(1.2).fmh(2.76)
  .decay(6).sustain(0).release(6).space("hall").gain(.12)

setcpm(54/3)

// One cycle is a bar of 3/4
// A 2 Hz binaural drone: each ear is detuned by 1 Hz, below the 3-30 Hz warning range
drone: note("[d2,a2]").slow(8).s("sine").binaural(2)
  .attack(4).sustain(1).release(6).gain(.22)

// A music box floating a little above your head: D, A, Bm, G, D, G, A, D
musicbox: note("<[f#5 e5 d5] [e5@2 c#5] [d5 b4 f#4] [g4@3] [a4 d5 f#5] [g5@2 b4] [a4 c#5 e5] [d5@3]>")
  .s("sine").fm(2).fmh(4).attack(.002).decay(1).sustain(0).release(1.5)
  .elevation(30).distance(2).room(.6).size(.85).gain(.16)

// A soft root on each downbeat
bass: note("<d2 a1 b1 g1 d2 g1 a1 d2>").s("triangle").timbre("soft")
  .attack(.01).decay(1).sustain(0).release(1).gain(.18)

// Warm brown noise and crickets far away
bed: s("brown").slow(8).lpf(400).gain(.07)
crickets: s("insect").slow(4).distance(8).gain(.05)
